/**
 * Shared health-check payload.
 *
 * Used by both the Fastify handler in `src/server` and the client-side
 * status indicators in `src/client`. Living in `src/shared` keeps the
 * wire shape in one place so server and client never drift.
 */
export interface HealthPayload {
  ok: boolean;
  galaxySeed: string;
}

/** Default payload used when no server config is available (tests, SSR). */
export const FALLBACK_HEALTH: HealthPayload = {
  ok: true,
  galaxySeed: "DRIFT-SEED-0001",
};

/** Pure constructor so tests can build snapshots without side effects. */
export function makeHealth(galaxySeed: string): HealthPayload {
  return { ok: true, galaxySeed };
}

import { describe, it, expect } from "vitest";
import { makeHealth, FALLBACK_HEALTH, type HealthPayload } from "./health.js";

describe("shared/health", () => {
  it("builds a payload with ok=true and the supplied seed", () => {
    const payload: HealthPayload = makeHealth("TEST-SEED");
    expect(payload.ok).toBe(true);
    expect(payload.galaxySeed).toBe("TEST-SEED");
  });

  it("exposes a fallback with the default seed", () => {
    expect(FALLBACK_HEALTH.ok).toBe(true);
    expect(FALLBACK_HEALTH.galaxySeed).toMatch(/^DRIFT-SEED-/);
  });
});

/**
 * Server smoke tests.
 *
 * Boots a Fastify app via `buildApp()` and exercises the `/api/health`
 * endpoint with `inject()`. No TCP port is bound; the test stays fast and
 * isolated from any other process that might be using `PORT`.
 */
import { describe, it, expect, beforeAll, afterAll } from "vitest";
import type { FastifyInstance } from "fastify";
import { buildApp } from "./server.js";
import { loadConfig } from "./config.js";
import type { HealthPayload } from "@shared/health.js";

describe("server /api/health", () => {
  let app: FastifyInstance;

  beforeAll(async () => {
    const config = loadConfig();
    app = await buildApp(config, { quietLogger: true });
    await app.ready();
  });

  afterAll(async () => {
    await app.close();
  });

  it("returns 200 with ok=true and a galaxySeed", async () => {
    const response = await app.inject({ method: "GET", url: "/api/health" });
    expect(response.statusCode).toBe(200);
    const body = response.json() as HealthPayload;
    expect(body.ok).toBe(true);
    expect(typeof body.galaxySeed).toBe("string");
    expect(body.galaxySeed.length).toBeGreaterThan(0);
  });
});

